function parseRefund(tokens: readonly string[]): [orderId: string, amountKobo: number] | string {
  const [orderId, raw] = tokens;
  if (!orderId?.startsWith("ORD-")) return "order id must start with ORD-";
  if (raw === undefined || !/^\d+$/.test(raw)) return "amount must be whole kobo";
  return [orderId, Number(raw)];
}

function exec(line: string): string {
  const [head, ...tokens] = line.trim().split(/\s+/);
  if (head !== "/refund") return `unknown command ${head}`;
  const parsed = parseRefund(tokens);
  return typeof parsed === "string" ? `usage: /refund <orderId> <amountKobo> (${parsed})` : `refund ${parsed[1]} on ${parsed[0]}`;
}

