function once<A extends unknown[], R>(fn: (...args: A) => R): (...args: A) => R {
  let done = false;
  let result: R;
  return (...args) => {
    if (!done) {
      result = fn(...args);
      done = true;
    }
    return result;
  };
}

let charges = 0;
const chargeCard = once((amountKobo: number) => {
  charges++;
  return `charged ${amountKobo}`;
});

console.log(chargeCard(5000), chargeCard(9000), charges);

