interface Gateway {
  charge(amountKobo: number): string;
}
interface GatewayClass {
  new (secretKey: string): Gateway;
  readonly provider: string;
}

class Paystack implements Gateway {
  static readonly provider = "paystack";
  constructor(private readonly key: string) {}
  charge(amountKobo: number): string {
    return `paystack charged ${amountKobo}`;
  }
}

const registry: readonly GatewayClass[] = [Paystack];

function createGateway(provider: string, key: string): Gateway {
  const GatewayType = registry.find((candidate) => candidate.provider === provider);
  if (!GatewayType) throw new Error(`no gateway called ${provider}`);
  return new GatewayType(key);
}

